@push('scripts')
<script>
$(function(){
    const modal=new bootstrap.Modal(document.getElementById('scrapIssueModal'));
    const productModal=new bootstrap.Modal(document.getElementById('scrapIssueProductModal'));
    const customerModal=new bootstrap.Modal(document.getElementById('scrapIssueCustomerModal'));
    const table=$('#scrapIssuesTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.scrap-issues.dt')),data:d=>{d.from_date=$('#scrapIssueFrom').val();d.to_date=$('#scrapIssueTo').val();}},columns:[
        {data:'id',orderable:false,searchable:false,render:(d,t,r,m)=>m.row+m.settings._iDisplayStart+1},{data:'actions',orderable:false,searchable:false,className:'text-center'},{data:'number',name:'number'},{data:'date_label',name:'issue_date'},{data:'customer_name',name:'customer_name',orderable:false},{data:'scrap_code',name:'scrap_code',orderable:false},{data:'scrap_name',name:'scrap_name',orderable:false},{data:'unit_label',orderable:false,searchable:false},{data:'quantity',name:'quantity',className:'text-end',render:d=>Number(d).toLocaleString(undefined,{maximumFractionDigits:4})},{data:'description',name:'description',defaultContent:'—'}
    ],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
    const products=$('#scrapIssueProductsTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.scrap-issues.products.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'unit_label',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}],drawCallback:()=>window.feather&&feather.replace()});
    const customers=$('#scrapIssueCustomersTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.scrap-issues.customers.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'actions',orderable:false,searchable:false}],drawCallback:()=>window.feather&&feather.replace()});
    function reset(){ $('#scrapIssueForm')[0].reset();$('#scrapIssueId,#scrapIssueCustomerId,#scrapIssueProductId').val('');$('#scrapIssueCustomerLabel,#scrapIssueProductLabel').val('');$('#scrapIssueDate').val(@json(now()->toDateString()));$('#scrapIssueModalTitle').text(@json(__('ui.scrap_issue.add'))); }
    $('#showScrapIssues').on('click',()=>table.ajax.reload());$('#scrapIssueFrom,#scrapIssueTo').on('change',()=>table.ajax.reload());
    $('#exportScrapIssues').on('click',function(e){e.preventDefault();window.location=this.href+'?'+$.param({from_date:$('#scrapIssueFrom').val(),to_date:$('#scrapIssueTo').val()});});
    $('#addScrapIssue').on('click',()=>{reset();$('#scrapIssueNumber').val(@json(__('ui.scrap_receipt.number_loading')));modal.show();$.get(@json(route('super.scrap-issues.number-preview'))).done(r=>$('#scrapIssueNumber').val(r.number)).fail(()=>$('#scrapIssueNumber').val(@json(__('ui.scrap_receipt.number_unavailable'))));});
    $('#chooseScrapIssueProduct').on('click',()=>productModal.show());$('#chooseScrapIssueCustomer').on('click',()=>customerModal.show());
    $(document).on('click','.btn-select-scrap-issue-product',function(){const b=$(this);$('#scrapIssueProductId').val(b.data('id'));$('#scrapIssueProductLabel').val(`${b.data('code')} — ${b.data('name')} (${b.data('unit')})`);productModal.hide();});
    $(document).on('click','.btn-select-scrap-issue-customer',function(){const b=$(this);$('#scrapIssueCustomerId').val(b.data('id'));$('#scrapIssueCustomerLabel').val(b.data('name'));customerModal.hide();});
    $(document).on('click','.btn-edit-scrap-issue',function(){const b=$(this);reset();$('#scrapIssueId').val(b.data('id'));$('#scrapIssueNumber').val(b.data('number'));$('#scrapIssueDate').val(b.data('date'));$('#scrapIssueCustomerId').val(b.data('customer'));$('#scrapIssueCustomerLabel').val(b.data('customer-name'));$('#scrapIssueProductId').val(b.data('product'));$('#scrapIssueProductLabel').val(`${b.data('code')} — ${b.data('name')} (${b.data('unit')})`);$('#scrapIssueQuantity').val(b.data('quantity'));$('#scrapIssueDescription').val(b.data('description'));$('#scrapIssueModalTitle').text(@json(__('ui.common.edit'))+' {{ __('ui.scrap_issue.title') }}');modal.show();});
    $(document).on('click','.btn-delete-scrap-issue',function(){const b=$(this);Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),text:@json(__('ui.scrap_issue.delete_help')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(!r.isConfirmed)return;$.ajax({url:b.data('url'),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',title:@json(__('ui.workflow.success')),text:x.message});}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:x.responseJSON?.message||@json(__('ui.workflow.save_failed'))}));});});
    $('#scrapIssueForm').on('submit',function(e){e.preventDefault();const id=$('#scrapIssueId').val(),url=id?@json(route('super.scrap-issues.update',['scrapIssue'=>'__ID__'])).replace('__ID__',id):@json(route('super.scrap-issues.store')),button=$('#saveScrapIssue').prop('disabled',true);$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',title:@json(__('ui.workflow.success')),text:`${r.message} (${r.number})`});}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||@json(__('ui.workflow.save_failed'))})).always(()=>button.prop('disabled',false));});
});
</script>
@endpush
